//! Fixed star catalog: 503 named stars with J2000.0 positions.
//!
//! Covers: all stars brighter than magnitude 3.0, all 15 Behenian stars,
//! all 27 Nakshatra yogatara (junction stars), the 4 Royal Stars,
//! major navigational stars, IAU-named stars down to about magnitude 5,
//! and notable stars from Chinese, Hellenistic, and Western astrological
//! traditions.
//!
//! ## Sources
//!
//! Every position, magnitude and proper motion is regenerated by
//! `tools/gen-star-catalog/regen_western_stars.py` from sources that carry no
//! non-commercial restriction:
//!
//! * the IAU Catalog of Star Names (IAU WGSN, Creative Commons Attribution):
//!   the J2000 position (6 decimals of a degree) of every star that has an
//!   IAU row;
//! * the Yale Bright Star Catalogue, 5th Revised Ed. (Hoffleit & Warren 1991,
//!   CDS V/50): proper motion, magnitude, and the position of every star
//!   without an IAU row (RA to 0.1 s, Dec to 1");
//! * for the four objects that are not in the Bright Star Catalogue:
//!   Gliese & Jahreiss, Preliminary Third Catalogue of Nearby Stars (CNS3, CDS
//!   V/70A, 1991) for the magnitude and proper motion of Barnard's Star,
//!   Proxima Centauri and Wolf 359 (and the position of Wolf 359, which is
//!   known to about 10 arcsec); Harris, Catalog of Parameters for Milky Way
//!   Globular Clusters (AJ 112, 1487, 1996, CDS VII/195) for the position and
//!   integrated magnitude of Omega Centauri (zero proper motion).
//!
//! Ecliptic longitude/latitude are derived from RA/Dec with the IAU 2006 mean
//! obliquity at J2000.0 (84381.406"). Names, designations and order are those
//! of the previous table. Seven entries are second components of stars that
//! the Bright Star Catalogue lists as one record (Algol B, Epsilon1 Tauri,
//! Alnasl2) or carry a Latin-letter designation found only in the catalogue's
//! variable-star column (Omicron Velorum, N Velorum, PP Carinae, L2 Puppis); the
//! generator names the record of each. Three entries could not be identified
//! from these sources and were removed rather than kept with unsourced values
//! (A Velorum, Q Velorum, Zeta Puppis2; the script says why).

// This is a data file: several stars have a visual magnitude of exactly 3.14
// (e.g. Talitha / ι Ursae Majoris). clippy::approx_constant false-positives on
// those magnitudes as if they were an attempt to spell π — they are not.
#![allow(clippy::approx_constant)]

use serde::{Deserialize, Serialize};

// ── J2000.0 obliquity for RA/Dec → ecliptic conversion ─────────────
/// Mean obliquity at J2000.0 in degrees (IAU 2006 value: 84381.406").
#[allow(dead_code)]
const OBLIQUITY_J2000_DEG: f64 = 84381.406 / 3600.0;

// ── Star data structure ────────────────────────────────────────────

/// A fixed star with J2000.0 equatorial and ecliptic coordinates.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FixedStar {
    /// Common name (e.g. "Sirius").
    pub name: &'static str,
    /// Bayer / Flamsteed designation (e.g. "Alpha Canis Majoris").
    pub designation: &'static str,
    /// Right ascension in degrees, J2000.0.
    pub ra_deg: f64,
    /// Declination in degrees, J2000.0.
    pub dec_deg: f64,
    /// Visual (apparent) magnitude.
    pub magnitude: f64,
    /// Proper motion in RA (mas/yr, includes cos(dec) factor).
    pub pm_ra: f64,
    /// Proper motion in Dec (mas/yr).
    pub pm_dec: f64,
    /// Ecliptic longitude in degrees, J2000.0.
    pub ecl_lon_deg: f64,
    /// Ecliptic latitude in degrees, J2000.0.
    pub ecl_lat_deg: f64,
}

// ── Helper: equatorial → ecliptic at J2000 ─────────────────────────

/// Convert J2000.0 equatorial (RA, Dec) in degrees to ecliptic (lon, lat)
/// in degrees, using the mean obliquity at J2000.0.
#[allow(dead_code)]
fn eq_to_ecl(ra_deg: f64, dec_deg: f64) -> (f64, f64) {
    let eps = OBLIQUITY_J2000_DEG.to_radians();
    let ra = ra_deg.to_radians();
    let dec = dec_deg.to_radians();

    let sin_eps = eps.sin();
    let cos_eps = eps.cos();
    let sin_dec = dec.sin();
    let cos_dec = dec.cos();
    let sin_ra = ra.sin();
    let cos_ra = ra.cos();

    let lon = (sin_ra * cos_eps + sin_dec / cos_dec * sin_eps).atan2(cos_ra);
    let lat = (sin_dec * cos_eps - cos_dec * sin_eps * sin_ra).asin();

    let lon_deg = lon.to_degrees().rem_euclid(360.0);
    let lat_deg = lat.to_degrees();
    (lon_deg, lat_deg)
}

/// Build a `FixedStar` from equatorial data; ecliptic coords are computed.
const fn star_raw(
    name: &'static str,
    designation: &'static str,
    ra_deg: f64,
    dec_deg: f64,
    magnitude: f64,
    pm_ra: f64,
    pm_dec: f64,
    ecl_lon_deg: f64,
    ecl_lat_deg: f64,
) -> FixedStar {
    FixedStar {
        name,
        designation,
        ra_deg,
        dec_deg,
        magnitude,
        pm_ra,
        pm_dec,
        ecl_lon_deg,
        ecl_lat_deg,
    }
}

